// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am) public {
        // Bound am to be at most 1 ether to avoid exceeding MinSum
        am = bound(am, 1 ether, 1 ether);

        // First call Collect to attempt reentrancy
        c.Collect(am);

        // Second call should succeed if locked_ is false after first call
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", am));
        assertTrue(success, "Second Collect should not revert");
    }
}

